#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll P = 1000000007;

int main() {
    string s, t;
    ll k;
    cin >> s >> t >> k;
    ll n = s.size();
    if (n != (ll)t.size()) {
        puts("0");
        return 0;
    }
    // c = number of rotation offsets of s that equal t.
    ll c = 0;
    for (ll j = 0; j < n; j++)
        if (s.compare(j, n - j, t, 0, n - j) == 0 && s.compare(0, j, t, n - j, j) == 0) c++;
    ll a = s == t, b = s != t;
    // Transition between states (matching, not matching) per step.
    ll x = ((c - 1) % P + P) % P, y = c % P, z = (n - c) % P, w = ((n - c - 1) % P + P) % P;
    while (k) {
        if (k & 1) {
            ll na = (x * a + y * b) % P, nb = (z * a + w * b) % P;
            a = na, b = nb;
        }
        ll nx = (x * x + y * z) % P, ny = (x * y + y * w) % P, nz = (z * x + w * z) % P, nw = (z * y + w * w) % P;
        x = nx, y = ny, z = nz, w = nw;
        k >>= 1;
    }
    printf("%lld\n", a);
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        final long P = 1000000007L;
        String s = next(), t = next();
        long k = nextLong();
        int n = s.length();
        if (n != t.length()) {
            System.out.println(0);
            return;
        }
        // c = number of rotation offsets of s that equal t.
        long c = 0;
        for (int j = 0; j < n; j++)
            if (s.regionMatches(j, t, 0, n - j) && s.regionMatches(0, t, n - j, j)) c++;
        long a = s.equals(t) ? 1 : 0, b = 1 - a;
        // Transition between states (matching, not matching) per step.
        long x = ((c - 1) % P + P) % P, y = c % P, z = (n - c) % P, w = ((n - c - 1) % P + P) % P;
        while (k > 0) {
            if ((k & 1) == 1) {
                long na = (x * a + y * b) % P, nb = (z * a + w * b) % P;
                a = na;
                b = nb;
            }
            long nx = (x * x + y * z) % P, ny = (x * y + y * w) % P, nz = (z * x + w * z) % P, nw = (z * y + w * w) % P;
            x = nx;
            y = ny;
            z = nz;
            w = nw;
            k >>= 1;
        }
        System.out.println(a);
    }
}

