import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	const P = 1000000007
	s, t := string(next()), string(next())
	k := nextInt()
	n := int64(len(s))
	if n != int64(len(t)) {
		fmt.Println(0)
		return
	}
	// c = number of rotation offsets of s that equal t.
	var c int64
	for j := int64(0); j < n; j++ {
		if s[j:] == t[:n-j] && s[:j] == t[n-j:] {
			c++
		}
	}
	var a, b int64
	if s == t {
		a = 1
	} else {
		b = 1
	}
	// Transition between states (matching, not matching) per step.
	x, y, z, w := ((c-1)%P+P)%P, c%P, (n-c)%P, ((n-c-1)%P+P)%P
	for ; k > 0; k >>= 1 {
		if k&1 == 1 {
			a, b = (x*a+y*b)%P, (z*a+w*b)%P
		}
		x, y, z, w = (x*x+y*z)%P, (x*y+y*w)%P, (z*x+w*z)%P, (z*y+w*w)%P
	}
	fmt.Println(a)
